-module(c48_bif_reachable_boolean_poison).
-export([handle_call/3]).

handle_call(true_branch, _From, State) ->
    case erlang:function_exported(erlang, c48_missing_export, 1) of
        true -> throw({noreply, State#{transport := unsafe_transport}});
        false -> {noreply, State}
    end;
handle_call(_Request, _From, State) ->
    case erlang:function_exported(erlang, is_atom, 1) of
        true -> {noreply, State};
        false -> throw({noreply, State#{transport := unsafe_transport}})
    end.
